def wait_for_database(host, port):
    import requests
    import time
    url = f"http://{host}:{port}/health"
    for _ in range(30):
        try:
            r = requests.get(url, verify=False, timeout=2)
            if r.status_code == 200:
                return True
        except requests.ConnectionError:
            time.sleep(1)
    return False
